create table if not exists public.spark_badge_awards(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.spark_members(id) on delete cascade,badge_code text not null,awarded_at timestamptz not null default now(),source text not null default 'system',unique(member_id,badge_code));
create table if not exists public.spark_campaigns(id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',flame_code text not null check(flame_code in('GOOD','SAFE','EARTH','CHALLENGE','CITIZEN')),starts_at timestamptz not null default now(),ends_at timestamptz,status text not null default 'draft' check(status in('draft','published','ended')),created_by uuid default auth.uid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.spark_badge_awards enable row level security; alter table public.spark_campaigns enable row level security;
create or replace function public.spark_sync_member_badges(p_member_id uuid) returns jsonb language plpgsql security definer set search_path='public' as $$ declare v_xp bigint; v_count bigint; begin select coalesce(sum(amount),0) into v_xp from spark_ledger where member_id=p_member_id; select count(*) into v_count from spark_activities a where a.member_id=p_member_id and exists(select 1 from spark_ledger l where l.activity_id=a.id group by l.activity_id having sum(l.amount)>0); if v_xp>=5 then insert into spark_badge_awards(member_id,badge_code) values(p_member_id,'FIRST_SPARK') on conflict do nothing; end if; if v_xp>=25 then insert into spark_badge_awards(member_id,badge_code) values(p_member_id,'GROWING_25') on conflict do nothing; end if; if v_xp>=50 then insert into spark_badge_awards(member_id,badge_code) values(p_member_id,'GROWING_50') on conflict do nothing; end if; if v_xp>=100 then insert into spark_badge_awards(member_id,badge_code) values(p_member_id,'LEVEL_100') on conflict do nothing; end if; if v_count>=25 then insert into spark_badge_awards(member_id,badge_code) values(p_member_id,'ACTION_25') on conflict do nothing; end if; return jsonb_build_object('ok',true,'total_xp',v_xp,'activity_count',v_count,'badges',(select coalesce(jsonb_agg(jsonb_build_object('code',badge_code,'awarded_at',awarded_at) order by awarded_at),'[]'::jsonb) from spark_badge_awards where member_id=p_member_id)); end $$;
create or replace function public.spark_hq_campaigns() returns setof public.spark_campaigns language plpgsql stable security definer set search_path='public' as $$ begin if not public.spark_is_hq_admin() then raise exception 'FORBIDDEN'; end if; return query select * from spark_campaigns order by created_at desc; end $$;
create or replace function public.spark_hq_save_campaign(p_id uuid,p_title text,p_description text,p_flame_code text,p_starts_at timestamptz,p_ends_at timestamptz) returns uuid language plpgsql security definer set search_path='public' as $$ declare v_id uuid; begin if not public.spark_is_hq_admin() then raise exception 'FORBIDDEN'; end if; if p_id is null then insert into spark_campaigns(title,description,flame_code,starts_at,ends_at,created_by) values(p_title,p_description,p_flame_code,coalesce(p_starts_at,now()),p_ends_at,auth.uid()) returning id into v_id; else update spark_campaigns set title=p_title,description=p_description,flame_code=p_flame_code,starts_at=coalesce(p_starts_at,starts_at),ends_at=p_ends_at,updated_at=now() where id=p_id returning id into v_id; end if; return v_id; end $$;
create or replace function public.spark_hq_set_campaign_status(p_id uuid,p_status text) returns boolean language plpgsql security definer set search_path='public' as $$ begin if not public.spark_is_hq_admin() then raise exception 'FORBIDDEN'; end if; if p_status not in('draft','published','ended') then raise exception 'BAD_STATUS'; end if; update spark_campaigns set status=p_status,updated_at=now() where id=p_id; return found; end $$;
create or replace function public.spark_public_campaigns(p_limit integer default 12) returns table(id uuid,title text,description text,flame_code text,starts_at timestamptz,ends_at timestamptz) language sql stable security definer set search_path='public' as $$ select c.id,c.title,c.description,c.flame_code,c.starts_at,c.ends_at from spark_campaigns c where c.status='published' and c.starts_at<=now() and(c.ends_at is null or c.ends_at>=now()) order by c.starts_at desc limit greatest(1,least(coalesce(p_limit,12),30)); $$;
grant execute on function public.spark_sync_member_badges(uuid) to authenticated; grant execute on function public.spark_hq_campaigns() to authenticated; grant execute on function public.spark_hq_save_campaign(uuid,text,text,text,timestamptz,timestamptz) to authenticated; grant execute on function public.spark_hq_set_campaign_status(uuid,text) to authenticated; grant execute on function public.spark_public_campaigns(integer) to anon,authenticated;